std::optional<Parameters> ExtractUserMessage(const Request& request) noexcept;
std::string_view ContentTypeByFileName(const std::string_view name) noexcept {
    if (name.ends_with(".html")) return "text/html";
    if (name.ends_with(".css")) return "text/css";
    if (name.ends_with(".js")) return "application/javascript";
    if (name.ends_with(".png")) return "image/png";
    if (name.ends_with(".jpg") || name.ends_with(".jpeg")) return "image/jpeg";
    if (name.ends_with(".gif")) return "image/gif";
    return "application/octet-stream";
}
std::string_view StatusCodeToMessage(const StatusCode code) noexcept {
    switch (code) {
        case StatusCode::OK: return "OK";
        case StatusCode::BadRequest: return "Bad Request";
        case StatusCode::Forbidden: return "Forbidden";
        case StatusCode::NotFound: return "Not Found";
    }
    return "Unknown Status Code";
}
std::ostream& operator<<(std::ostream& os, const StatusCode code) noexcept {
    os << static_cast<std::uint32_t>(code);
    return os;
}
std::uint32_t StatusCodeToInteger(const StatusCode code) noexcept {
    return static_cast<std::uint32_t>(code);
}
std::string_view MethodToString(const Method method) noexcept {
    switch (method) {
        case Method::Get: return "GET";
        case Method::Post: return "POST";
        case Method::Put: return "PUT";
        case Method::Patch: return "PATCH";
        case Method::Delete: return "DELETE";
    }
    return "UNKNOWN";
}
std::string to_string(const Method method) noexcept {
    return std::string(MethodToString(method));
}
Method StringToMethod(std::string str) {
    if (str == "GET" || str == "get") return Method::Get;
    if (str == "POST" || str == "post") return Method::Post;
    if (str == "PUT" || str == "put") return Method::Put;
    if (str == "PATCH" || str == "patch") return Method::Patch;
    if (str == "DELETE" || str == "delete") return Method::Delete;
    throw std::invalid_argument("Invalid HTTP method: " + str);
}
std::ostream& operator<<(std::ostream& os, const Method method) noexcept {
    os << to_string(method);
    return os;
}
char DecodeURLEncodedCharacter(const std::string& str) {
    if (str.size() != 3 || str[0] != '%') throw std::invalid_argument("Invalid URL encoded character: " + str);
    int value = 0;
    for (std::size_t i = 1; i < 3; ++i) {
        char c = str[i];
        if (c >= '0' && c <= '9') value = value * 16 + (c - '0');
        else if (c >= 'A' && c <= 'F') value = value * 16 + (c - 'A' + 10);
        else if (c >= 'a' && c <= 'f') value = value * 16 + (c - 'a' + 10);
        else throw std::invalid_argument("Invalid URL encoded character: " + str);
    }
    return static_cast<char>(value);
}
std::string DecodeURLEncodedString(const std::string& str) {
    std::string result;
    for (std::size_t i = 0; i < str.size(); ++i) {
        if (str[i] == '%' && i + 2 < str.size()) {
            try {
                char c = DecodeURLEncodedCharacter(str.substr(i, 3));
                result += c;
                i += 2;
            } catch (...) {
                throw std::invalid_argument("Invalid URL encoded string: " + str);
            }
        } else if (str[i] == '+') {
            result += ' ';
        } else {
            result += str[i];
        }
    }
    return result;
}
std::string HTMLPlaceholder(std::string_view key) noexcept {
    return "{{{" + std::string(key) + "}}}";
}
std::string PutParamIntoHTML(std::string html, const Parameters& params) {
    for (const auto& [key, value] : params) {
        std::string placeholder = HTMLPlaceholder(key);
        size_t pos = 0;
        while ((pos = html.find(placeholder, pos)) != std::string::npos) {
            html.replace(pos, placeholder.length(), value);
            pos += value.length();
        }
    }
    return html;
}

std::filesystem::path ConnectionImpl::root_dir_;
void ConnectionImpl::SetRootDirectory(std::filesystem::path dir) noexcept {
    root_dir_ = std::move(dir);
}
std::filesystem::path ConnectionImpl::GetRootDirectory() noexcept {
    return root_dir_;
}
ConnectionImpl::ConnectionImpl(const FileDescriptor socket) noexcept : socket_(socket) {}
ConnectionImpl::~ConnectionImpl() noexcept {
    Close();
}
void ConnectionImpl::Close() noexcept {
    if (Valid()) {
        io::close(socket_);
        socket_ = invalid_file_descriptor;
    }
}
FileDescriptor ConnectionImpl::Socket() const noexcept {
    return socket_;
}
bool ConnectionImpl::KeepAlive() const noexcept {
    return keep_alive_;
}
bool ConnectionImpl::Valid() const noexcept {
    return socket_ != invalid_file_descriptor && io::is_valid(socket_);
}
std::size_t ConnectionImpl::Receive() {
    if (!Valid()) throw std::runtime_error("Invalid connection");
    return read_buf_.ReadFrom(io::IReadWriter(socket_));
}
std::size_t ConnectionImpl::Send() {
    if (!Valid()) throw std::runtime_error("Invalid connection");
    return write_buf_.WriteTo(io::IReadWriter(socket_));
}
bool ConnectionImpl::Process() noexcept {
    try {
        Request request;
        request.Parse(read_buf_);
        Response response(root_dir_);
        StatusCode code = StatusCode::OK;
        auto file_opt = response.Build(write_buf_, std::filesystem::path(request.Path()), code);
        if (!file_opt) {
            response.Build(write_buf_, code, "File not found");
        }
        keep_alive_ = request.KeepAlive();
        return true;
    } catch (...) {
        Response response(root_dir_);
        response.Build(write_buf_, StatusCode::BadRequest, "Invalid request");
        return false;
    }
}

