#include "request.h"
#include "util.h"
#include <cassert>
#include <regex>
#include <stdexcept>

class Request::State {
public:
    explicit State(Request& parser) noexcept : parser_(parser) {}
    virtual ~State() noexcept = default;
    virtual void Parse(const std::string& content) = 0;
protected:
    Request& parser_;
};

class NotStarted : public State {
public:
    using State::State;
    void Parse(const std::string& line) override {
        if (line.empty()) return;
        ParseStatusLine(line);
        parser_.SetState(std::make_unique<Header>(parser_));
    }
private:
    void ParseStatusLine(const std::string& line) {
        std::regex pattern("^([A-Z]+)\s+([^\s]+)\s+HTTP/(\d+)\.(\d+)$");
        std::smatch matches;
        if (!std::regex_match(line, matches, pattern)) throw std::invalid_argument("Invalid request line: " + line);
        parser_.method_ = StringToMethod(matches[1].str());
        parser_.path_ = matches[2].str();
        parser_.version_ = "HTTP/" + matches[3].str() + "." + matches[4].str();
    }
};

class Header : public State {
public:
    using State::State;
    void Parse(const std::string& line) override {
        if (line.empty()) {
            parser_.SetState(std::make_unique<Body>(parser_));
            return;
        }
        size_t colon_pos = line.find(':');
        if (colon_pos == std::string::npos) throw std::invalid_argument("Invalid header line: " + line);
        std::string key = line.substr(0, colon_pos);
        std::string value = line.substr(colon_pos + 1);
        while (!value.empty() && (value[0] == ' ' || value[0] == '\t')) {
            value.erase(value.begin());
        }
        parser_.headers_[key] = value;
    }
};

class Body : public State {
public:
    using State::State;
    void Parse(const std::string& body) override {
        if (parser_.Method() == http::Method::Post) {
            ParsePost(body);
        }
        parser_.SetState(std::make_unique<Finished>(parser_));
    }
private:
    void ParsePost(const std::string& body) {
        auto content_type = parser_.Header("Content-Type");
        if (!content_type || *content_type != "application/x-www-form-urlencoded") return;
        ParseURLEncodedPost(body);
    }
    void ParseURLEncodedPost(const std::string& body) {
        size_t pos = 0;
        while (pos < body.size()) {
            size_t amp_pos = body.find('&', pos);
            if (amp_pos == std::string::npos) amp_pos = body.size();
            size_t eq_pos = body.find('=', pos);
            if (eq_pos == std::string::npos || eq_pos > amp_pos) {
                throw std::invalid_argument("Invalid URL encoded post data: " + body);
            }
            std::string key = DecodeURLEncodedString(body.substr(pos, eq_pos - pos));
            std::string value = DecodeURLEncodedString(body.substr(eq_pos + 1, amp_pos - eq_pos - 1));
            parser_.post_[key] = value;
            pos = amp_pos + 1;
        }
    }
};

class Finished : public State {
public:
    using State::State;
    [[noreturn]] void Parse(const std::string& content) override {
        throw std::logic_error("Request already finished");
    }
};

#pragma once
#include "containers/buffer.h"
#include "http.h"
#include "util.h"
#include <filesystem>
#include <optional>

class Response {
public:
    explicit Response(std::filesystem::path root_dir) noexcept;
    ~Response() noexcept;
    Response(const Response&) = delete;
    Response(Response&&) = delete;
    Response& operator=(const Response&) = delete;
    Response& operator=(Response&&) = delete;
    Response& SetKeepAlive(bool set) noexcept;
    std::optional<MappedReadOnlyFile> Build(Buffer& buf, std::filesystem::path file, StatusCode& code) noexcept;
    void Build(Buffer& buf, std::filesystem::path html, const Parameters& params, StatusCode& code) noexcept;
    void Build(Buffer& buf, StatusCode code, std::string msg = "") noexcept;
    void Clear() noexcept;
    void Build(Buffer& buf, const Parameters* params = nullptr) noexcept;
private:
    void CheckFile();
    void MapFile();
    void AddStatusLine(Buffer& buf) const noexcept;
    void AddHeaders(Buffer& buf) const noexcept;
    void AddMappedContent(Buffer& buf) noexcept;
    void AddParamContent(Buffer& buf, const Parameters& params) const noexcept;
    void AddPredefinedErrorContent(Buffer& buf, std::string_view msg = "") noexcept;
    std::filesystem::path root_dir_;
    std::filesystem::path file_path_;
    MappedReadOnlyFile file_;
    bool keep_alive_ {false};
    StatusCode status_code_ {StatusCode::OK};
};

#include "response.h"
#include <cassert>
#include <sstream>

Response::Response(std::filesystem::path root_dir) noexcept : root_dir_(std::move(root_dir)) {}
Response::~Response() noexcept = default;
void Response::Clear() noexcept {
    file_path_.clear();
    file_ = MappedReadOnlyFile{};
    status_code_ = StatusCode::OK;
}
Response& Response::SetKeepAlive(const bool set) noexcept {
    keep_alive_ = set;
    return *this;
}
std::optional<MappedReadOnlyFile> Response::Build(Buffer& buf, std::filesystem::path file, StatusCode& code) noexcept {
    Clear();
    file_path_ = root_dir_ / file;
    if (!std::filesystem::exists(file_path_) || !std::filesystem::is_regular_file(file_path_)) {
        status_code_ = StatusCode::NotFound;
        AddStatusLine(buf);
        AddHeaders(buf);
        AddPredefinedErrorContent(buf, "File not found");
        code = status_code_;
        return std::nullopt;
    }
    MapFile();
    status_code_ = StatusCode::OK;
    AddStatusLine(buf);
    AddHeaders(buf);
    AddMappedContent(buf);
    code = status_code_;
    return file_;
}
void Response::Build(Buffer& buf, std::filesystem::path html, const Parameters& params, StatusCode& code) noexcept {
    Clear();
    file_path_ = root_dir_ / html;
    if (!std::filesystem::exists(file_path_) || !std::filesystem::is_regular_file(file_path_)) {
        status_code_ = StatusCode::NotFound;
        AddStatusLine(buf);
        AddHeaders(buf);
        AddPredefinedErrorContent(buf, "File not found");
        code = status_code_;
        return;
    }
    MapFile();
    status_code_ = StatusCode::OK;
    AddStatusLine(buf);
    AddHeaders(buf);
    AddParamContent(buf, params);
    code = status_code_;
}
void Response::Build(Buffer& buf, const StatusCode code, std::string msg) noexcept {
    Clear();
    status_code_ = code;
    AddStatusLine(buf);
    AddHeaders(buf);
    if (!msg.empty()) {
        AddPredefinedErrorContent(buf, msg);
    }
}
void Response::Build(Buffer& buf, const Parameters* const params) noexcept {
    Clear();
    status_code_ = StatusCode::OK;
    AddStatusLine(buf);
    AddHeaders(buf);
    if (params && !params->empty()) {
        AddParamContent(buf, *params);
    }
}
void Response::AddStatusLine(Buffer& buf) const noexcept {
    buf.Append(std::string("HTTP/1.1 ") + std::to_string(static_cast<int>(status_code_)) + " " + StatusCodeToMessage(status_code_) + new_line);
}
void Response::AddHeaders(Buffer& buf) const noexcept {
    buf.Append("Content-Type: " + ContentTypeByFileName(file_path_.extension().string()) + new_line);
    buf.Append("Connection: " + (keep_alive_ ? "keep-alive" : "close") + new_line);
    buf.Append(new_line);
}
void Response::AddMappedContent(Buffer& buf) noexcept {
    if (!file_) return;
    buf.Append(file_.data(), file_.size());
}
void Response::AddParamContent(Buffer& buf, const Parameters& params) const noexcept {
    std::string html = PutParamIntoHTML(std::string(file_), params);
    buf.Append(html);
}
void Response::AddPredefinedErrorContent(Buffer& buf, const std::string_view msg) noexcept {
    buf.Append("<html><body><h1>" + std::string(msg) + "</h1></body></html>");
}
